WITH flattened AS (SELECT id, customer_id, created_at, coupon_codes, attr_key, attr_value FROM carts LATERAL VIEW EXPLODE(attributes) li AS attr_key, attr_value), enriched AS (SELECT e.*, b.age, b.segment FROM flattened e LEFT JOIN customers b ON e.customer_id = b.id), filtered AS (SELECT id, attr_key, attr_value, age, segment, CAST(created_at AS DATE) AS created_at_day FROM enriched WHERE age >= 58), enriched_carts AS (SELECT id, attr_key, attr_value, age, segment, created_at_day, ROW_NUMBER() OVER (ORDER BY age DESC, id ASC, attr_key ASC) AS event_seq, AVG(age) OVER (PARTITION BY segment ORDER BY created_at_day ASC, id ASC, attr_key ASC ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS age_avg_2 FROM filtered), deduped AS (SELECT * FROM (SELECT *, RANK() OVER (PARTITION BY segment, attr_key ORDER BY created_at_day DESC NULLS LAST) AS latest_rank FROM enriched_carts) t WHERE latest_rank = 1), stats AS (SELECT DATE_TRUNC('WEEK', created_at_day) AS week_start, SUM(CASE WHEN attr_key = 'utm_source' THEN age ELSE 0 END) AS utm_source_age, COUNT_IF(segment = 'Consumer') AS consumer_events FROM deduped GROUP BY 1) SELECT week_start, utm_source_age, consumer_events FROM stats;
